import{_ as i,l as s,o as e,c as l,v as t,p as n,x as r,d as c,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"RPC 语义","description":"","frontmatter":{"title":"RPC 语义","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rpc-semantics.md","filePath":"cs/rpc-semantics.md","lastUpdated":1789023840000}'),h={name:"cs/rpc-semantics.md"};function m(P,a,_,C,E,u){const o=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="rpc-语义" tabindex="-1">RPC 语义 <a class="header-anchor" href="#rpc-语义" aria-label="Permalink to &quot;RPC 语义&quot;">​</a></h1><div class="epigraph"><p>远程调用看起来像本地过程，失败模式不像。至少一次、至多一次、恰好一次是对「过程执行了几次」的承诺，不是营销。</p><footer>—— 据 Birrell and Nelson, Implementing Remote Procedure Calls, TOCS 1984；Spector, Performing Remote Operations Efficiently, CACM 1982 整理</footer></div><p>共识单元以<a href="/cs/pow-blockchain-consensus">PoW 直觉</a>封口。系统模式课序从通信开始。缺口不是再选主，而是<strong>一次调用在故障下执行了几遍</strong>。本课钉 RPC 的执行语义。后课投递语义把消息层的至少/至多说清，二者常被混名。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Birrell–Nelson：桩、报文、绑定、超时。本地调用：进程活则恰好执行一次。RPC：请求丢、应答丢、服务器崩在执行前/中/后，客户端超时后看见的都是「没回来」。缺口：重试会把「执行前崩」变成成功，也会把「执行后应答丢」变成执行两遍。</p><p>Spector 把远程操作分成至少一次、至多一次等。至少一次：重试直到一次成功应答，执行次数 \\(\\ge 1\\)（若终成功）。至多一次：执行次数 \\(\\le 1\\)，可能零次（超时后不知道）。恰好一次：又回到共识与幂等的税。</p><p><span class="marginnote">「at-most-once」常靠服务器端调用 ID 表实现，表要有过期，过期后又滑回至少一次。本课先定词。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>接口必须声明语义。默认最常见的工程是：超时重试 + 希望处理函数幂等 ≈ 试图至少一次。真至多一次：服务器记住 <code>(client, xid)</code> 的结果。真恰好一次：把调用当 RSM 命令或用事务。</p>',9)),(e(),n(d,null,{default:r(()=>[p(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20CALL%5B%22RPC%22%5D%20--%3E%20TO%5B%22%E8%B6%85%E6%97%B6%22%5D%0A%20%20TO%20--%3E%20RET%5B%22%E9%87%8D%E8%AF%95%22%5D%0A%20%20RET%20--%3E%20DUP%5B%22%E5%8F%AF%E8%83%BD%E4%BA%8C%E6%AC%A1%E6%89%A7%E8%A1%8C%22%5D%0A%20%20DUP%20--%3E%20IDEM%5B%22%E8%A6%81%E5%B9%82%E7%AD%89%20%E5%90%8E%E8%AF%BE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>不要把 TCP 「恰好一次字节流」当成恰好一次过程：流保证段，不保证应用执行与应答的原子。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>崩溃恢复：服务器若在执行后、记 xid 前崩，至多一次表会漏，重试再执行。xid 必须与副作用同事务落盘——又接到 WAL。无状态服务器最容易做成至少一次。</p><p>绑定与版本：桩与服务器 stub 不一致是另一类失败，不是执行次数。本课点名。部分同步下超时只是<a href="/cs/failure-detectors">检测器</a>，不能当「对方没执行」的证明——这是 FLP 在 RPC 上的投影。</p><p>本课不写 gRPC 流式 API 全文，不写限价簿下单 RPC。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把消息队列的投递保证写完（下一课）。不引入 Saga。后课默认：说到 RPC，先问三次语义；超时后的知识状态是「不知道」，除非服务器给了持久 xid 结果。幂等键是把至少一次压成效果一次。</p><p>本地过程的等式在远程不成立。失败是常态规格，不是异常注释。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>至少一次、至多一次、恰好一次谈的是执行次数。</li><li>超时后客户端不知道；重试提高执行次数。</li><li>TCP 字节可靠 ≠ 过程恰好一次。</li><li>出处：Birrell and Nelson, TOCS 1984；Spector, 1982。</li></ul>',10))])}const T=i(h,[["render",m]]);export{A as __pageData,T as default};
